from pathlib import Path
import base64,html
root=Path('/mnt/data/noboribetsu_v008_work/outputs');dst=Path('/mnt/data/Noboribetsu_Date_V008_R1_Review.html')
labels=[('waraji_front','草鞋屋正面','二樓紙窗襯板、簷下木構、石基座'),('waraji_eave','草鞋屋二樓','簷下木構與窗格層次'),('utsuroi','變裝攝影館（未修改）','對照確認其他建築沒有意外變動')]
blocks=[]
for i,(key,title,desc) in enumerate(labels):
 a=base64.b64encode((root/f'{key}_V007.png').read_bytes()).decode()
 b=base64.b64encode((root/f'{key}_V008.png').read_bytes()).decode()
 blocks.append(f'''<section><h2>{title}</h2><p>{desc}</p><div class="compare" id="c{i}"><img class="after" alt="V008 {title}" src="data:image/png;base64,{b}"><img class="before" alt="V007 {title}" src="data:image/png;base64,{a}"><div class="bar"></div><span class="tag left">V007 原版</span><span class="tag right">V008 候選</span></div><label class="slide-label" for="s{i}">拖曳滑桿查看差異</label><input type="range" id="s{i}" min="0" max="100" value="50" oninput="document.querySelector('#c{i}').style.setProperty('--split',this.value+'%')"></section>''')
out=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>登別伊達時代村 V008｜3D 建築精修對照</title><style>:root{{color-scheme:light}}*{{box-sizing:border-box}}body{{margin:0;background:#f4f3eb;color:#25362c;font-family:system-ui,"Noto Sans TC",sans-serif;line-height:1.6}}main{{max-width:1120px;margin:auto;padding:24px 18px 54px}}header{{padding:18px 0 6px;border-bottom:1px solid #d7dacc}}h1{{font-size:clamp(23px,4vw,35px);margin:0}}h2{{font-size:22px;margin:0 0 7px}}.sub{{color:#536356}}section{{padding:22px 0;border-bottom:1px solid #d7dacc}}section p{{color:#566457;margin:0 0 12px}}.compare{{position:relative;--split:50%;width:100%;aspect-ratio:8 / 5;overflow:hidden;background:#fff;border-radius:10px;border:1px solid #d3d7cb}}.compare img{{width:100%;height:100%;object-fit:cover;position:absolute;left:0;top:0}}.compare .before{{clip-path:inset(0 calc(100% - var(--split)) 0 0)}}.compare .bar{{position:absolute;top:0;bottom:0;left:var(--split);border-left:3px solid white;filter:drop-shadow(0 0 2px #243);pointer-events:none}}.tag{{position:absolute;top:12px;padding:5px 10px;border-radius:7px;background:#fffdfaeb;color:#203627;font-size:13px}}.left{{left:12px}}.right{{right:12px}}input[type=range]{{width:100%;accent-color:#4c8372;cursor:ew-resize}}.slide-label{{display:block;margin:8px 0;font-size:14px}}.note{{background:#e8eade;border-radius:10px;padding:12px 18px;margin-top:22px}}.note p{{margin:.6em 0}}a{{color:#326756}}footer{{margin-top:26px;font-size:13px;color:#536258}}@media(max-width:600px){{main{{padding:14px}}h2{{font-size:19px}}.tag{{font-size:11px;padding:4px 7px}}}}</style></head><body><main><header><h1>登別伊達時代村｜V008 草鞋屋建築細節</h1><p class="sub">用實際 GLB 重新渲染的 V007／V008 同鏡位比較｜拖曳滑桿查看變化</p></header>{''.join(blocks)}<aside class="note"><strong>資料真實性說明</strong><p>草鞋屋的二樓紙窗與簷下構件，是參考<a target="_blank" rel="noopener noreferrer" href="https://edo-trip.jp/wp/wp-content/uploads/2018/04/f0272006b776b4fd294606a2d4a80622-800x600.jpg">官方網站舊照片</a>進行的「結構推估」；草鞋屋於 2025 年重新裝修，不能宣稱這就是 2026 年外觀。變裝攝影館本輪沒有修改。</p><p>所有比較圖來自實際 GLB 的 VTK 幾何渲染，不是 Blender Cycles 或 WebGL 實際遊玩畫面。模型內沒有使用官方照片作貼圖。</p><p>231.6 公尺道路、碰撞與原本 V007 外觀均保留；WebGL2／Android／私人網站及 Blender 正式回寫仍未驗收。</p></aside><footer>V008 R1 • 2026-11-01 • 可獨立離線開啟，所有圖片已內嵌，不需網路</footer></main></body></html>'''
dst.write_text(out,encoding='utf-8');print(dst,dst.stat().st_size)